sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	//MSSRBXCE-494: BR-#2 Started

	if(isJsonString(current.swb_payload_client_disagree)){

		var inPayload = JSON.parse(current.swb_payload_client_disagree);
		var finObjects= {};
		var finObjType;
		//get payload classification
		try{
			var classification = inPayload[0].Classification_Type.toString();
			}
		catch(e){
			gs.info("Error while parsing the JSON" + e);
			}
		// get primary financial object type based on classification
		if(classification.indexOf("Allocation Level")!==-1){
			finObjType="Allocation";
		}else{
			finObjType="Block Trade";
		}

		for(var i=0;i<inPayload.length;i++){
			var finObj="";
			if(finObjType=="Allocation"){
			finObj = inPayload[i].Allocation_ID.toString();
			}else{
			finObj = inPayload[i].Block_Trade_ID.toString();
			}


			if (finObj!="" && finObjects[finObj]==undefined){
				finObjects[finObj]=[inPayload[i]]; //get the list of unique blocktrades
			} else {
				finObjects[finObj].push(inPayload[i]);
			}
		}

		//create swb payload for every financial object
		for(var key in finObjects){

			var grInstr = new GlideRecord('x_hsb11_hsbcmss_eh_swb_final_payload_responses');
			grInstr.initialize();
			grInstr.parent_email_case=current.sys_id;
			grInstr.payload = JSON.stringify(finObjects[key]);
			grInstr.client_response="Client Disagree";
			grInstr.financial_object_from_payload=key.toString();
			grInstr.financial_object_type=finObjType;
			grInstr.insert();
		}

	}else{
		current.work_notes = "Not a valid JSON - cannot convert Client Disagree payload into actionable items";
		current.update();
	}

function isJsonString(str){
	try {
		JSON.parse(str);
	} catch(e){
		return false;
	}
	return true;
}
//MSSRBXCE-494: BR-#2 Ended
})(current, previous);
